from pydantic import BaseModel, Field


# Pydantic model: create the structure of the body
# FastAPI validate automatically incoming data (types + required fields)
# Note: the id is generated by the server while title + content by the client
class DocumentCreate(BaseModel):
    model_config = {"str_strip_whitespace": True}   # Remove white space and the beginning or end of the str like " abc " to "abc"
    title: str = Field(min_length=1)                # Accept as min 1 char
    content: str
